fn spawn_hud_metric(
    parent: &mut ChildSpawnerCommands,
    render: &RenderAssets,
    metric: HudMetric,
    source_path: &str,
    width: Val,
) {
    spawn_hud_metric_sized(parent, render, metric, source_path, width, 36.0, 20.0);
}

fn spawn_hud_metric_sized(
    parent: &mut ChildSpawnerCommands,
    render: &RenderAssets,
    metric: HudMetric,
    source_path: &str,
    width: Val,
    icon_size: f32,
    font_size: f32,
) {
    parent
        .spawn((
            HudMetricRow,
            Node {
                width,
                height: px(44),
                flex_shrink: 0.0,
                align_self: AlignSelf::Center,
                align_items: AlignItems::Center,
                overflow: Overflow::clip(),
                ..default()
            },
        ))
        .with_children(|metric_parent| {
            if let Some(icon) = top_bar_texture(render, source_path) {
                metric_parent.spawn((
                    ImageNode::new(icon),
                    Node {
                        width: px(icon_size),
                        height: px(icon_size),
                        flex_shrink: 0.0,
                        align_self: AlignSelf::Center,
                        ..default()
                    },
                ));
            }
            metric_parent
                .spawn(Node {
                    flex_grow: 1.0,
                    height: px(40),
                    align_self: AlignSelf::Center,
                    flex_direction: FlexDirection::Column,
                    justify_content: JustifyContent::Center,
                    padding: UiRect::left(px(5)),
                    overflow: Overflow::clip(),
                    ..default()
                })
                .with_children(|values| {
                    values.spawn((
                        metric,
                        Text::new("0"),
                        TextFont {
                            font_size: FontSize::Px(font_size),
                            ..default()
                        },
                        TextColor(Color::srgb(0.91, 0.89, 0.81)),
                        TextLayout::no_wrap(),
                        Node {
                            height: px(23),
                            flex_shrink: 0.0,
                            overflow: Overflow::clip(),
                            ..default()
                        },
                    ));
                    if metric.shows_maximum() {
                        values.spawn((
                            HudMetricMaximum(metric),
                            Text::new("/0"),
                            TextFont {
                                font_size: FontSize::Px((font_size * 0.55).max(9.0)),
                                ..default()
                            },
                            TextColor(Color::srgb(0.72, 0.72, 0.68)),
                            TextLayout::no_wrap(),
                            Node {
                                height: px(12),
                                flex_shrink: 0.0,
                                overflow: Overflow::clip(),
                                ..default()
                            },
                        ));
                    }
                });
        });
}

