fn spawn_town_dialog_button(
    parent: &mut ChildSpawnerCommands,
    action: TownDialogAction,
    label: &str,
    render: &RenderAssets,
    tab_index: i32,
) {
    parent
        .spawn((
            action,
            Button,
            TabIndex(tab_index),
            authored_ui_image(
                render,
                MAIN_MENU_TEXTURE_PATHS[0],
                main_menu_texture(render, MAIN_MENU_TEXTURE_PATHS[0]),
            ),
            Node {
                width: percent(48.0),
                height: px(52),
                justify_content: JustifyContent::Center,
                align_items: AlignItems::Center,
                ..default()
            },
        ))
        .with_children(|button| {
            button.spawn((
                Text::new(label),
                TextFont {
                    font_size: FontSize::Px(20.0),
                    ..default()
                },
                TextColor(Color::srgb(0.827, 0.745, 0.498)),
                Pickable::IGNORE,
            ));
        });
}

fn spawn_town_dialogs(commands: &mut Commands, render: &RenderAssets, saves: &[TownSaveEntry]) {
    for page in [MenuPage::NewTown, MenuPage::LoadTown] {
        commands
            .spawn((
                StateEntity,
                TownDialogRoot(page),
                Visibility::Hidden,
                GlobalZIndex(185),
                BackgroundColor(Color::srgba(0.004, 0.006, 0.012, 0.88)),
                Node {
                    position_type: PositionType::Absolute,
                    left: px(0),
                    top: px(0),
                    width: percent(100.0),
                    height: percent(100.0),
                    justify_content: JustifyContent::Center,
                    align_items: AlignItems::Center,
                    ..default()
                },
            ))
            .with_children(|overlay| {
                overlay
                    .spawn((
                        TabGroup::default(),
                        BackgroundColor(Color::srgb(0.035, 0.046, 0.09)),
                        BorderColor::all(Color::srgb(0.827, 0.745, 0.498)),
                        Node {
                            width: percent(52.0),
                            max_width: px(840),
                            min_height: px(390),
                            max_height: percent(82.0),
                            border: UiRect::all(px(3)),
                            border_radius: BorderRadius::all(px(34)),
                            padding: UiRect::all(px(42)),
                            flex_direction: FlexDirection::Column,
                            row_gap: px(20),
                            overflow: Overflow::clip(),
                            ..default()
                        },
                    ))
                    .with_children(|panel| {
                        panel.spawn((
                            settings_panel_ui_image(
                                render,
                                SETTINGS_BACKGROUND_TEXTURE_PATH,
                                main_menu_texture(render, SETTINGS_BACKGROUND_TEXTURE_PATH),
                            ),
                            Pickable::IGNORE,
                            Node {
                                position_type: PositionType::Absolute,
                                left: px(3),
                                top: px(3),
                                right: px(3),
                                bottom: px(3),
                                ..default()
                            },
                        ));
                        panel.spawn((
                            UiDisplayFont,
                            Text::new(if page == MenuPage::NewTown {
                                "NAME YOUR TOWN"
                            } else {
                                "LOAD A TOWN"
                            }),
                            TextFont {
                                font_size: FontSize::Px(32.0),
                                ..default()
                            },
                            TextLayout::justify(Justify::Center),
                            TextColor(Color::WHITE),
                            Pickable::IGNORE,
                            Node {
                                width: percent(100.0),
                                ..default()
                            },
                        ));
                        if page == MenuPage::NewTown {
                            panel.spawn((
                                Text::new("The name determines the deterministic world seed and its independent save file."),
                                TextFont {
                                    font_size: FontSize::Px(17.0),
                                    ..default()
                                },
                                TextLayout::justify(Justify::Center),
                                TextColor(Color::srgb(0.84, 0.88, 0.94)),
                                Pickable::IGNORE,
                            ));
                            panel.spawn((
                                TownNameField,
                                EditableText {
                                    max_characters: Some(80),
                                    ..EditableText::new("")
                                },
                                SelectAllOnFocus,
                                TabIndex(0),
                                TextCursorStyle {
                                    color: Color::WHITE,
                                    selected_text_color: Some(Color::BLACK),
                                    ..default()
                                },
                                TextFont {
                                    font_size: FontSize::Px(24.0),
                                    ..default()
                                },
                                TextColor(Color::WHITE),
                                BackgroundColor(Color::srgb(0.018, 0.026, 0.055)),
                                BorderColor::all(Color::srgb(0.40, 0.49, 0.67)),
                                Node {
                                    width: percent(100.0),
                                    height: px(56),
                                    border: UiRect::all(px(2)),
                                    border_radius: BorderRadius::all(px(8)),
                                    padding: UiRect::axes(px(14), px(10)),
                                    overflow: Overflow::clip_x(),
                                    ..default()
                                },
                            ));
                            panel
                                .spawn(Node {
                                    width: percent(100.0),
                                    height: px(52),
                                    justify_content: JustifyContent::SpaceBetween,
                                    ..default()
                                })
                                .with_children(|buttons| {
                                    spawn_town_dialog_button(
                                        buttons,
                                        TownDialogAction::Back,
                                        "Back",
                                        render,
                                        1,
                                    );
                                    spawn_town_dialog_button(
                                        buttons,
                                        TownDialogAction::Create,
                                        "Create Town",
                                        render,
                                        2,
                                    );
                                });
                        } else {
                            panel
                                .spawn((
                                    TownLoadList,
                                    ScrollPosition::default(),
                                    Node {
                                        width: percent(100.0),
                                        flex_grow: 1.0,
                                        flex_direction: FlexDirection::Column,
                                        row_gap: px(8),
                                        overflow: Overflow::scroll_y(),
                                        ..default()
                                    },
                                ))
                                .with_children(|list| {
                                    if saves.is_empty() {
                                        list.spawn((
                                            Text::new("No saved towns were found."),
                                            TextFont {
                                                font_size: FontSize::Px(19.0),
                                                ..default()
                                            },
                                            TextColor(Color::WHITE),
                                        ));
                                    }
                                    for (index, save) in saves.iter().enumerate() {
                                        list.spawn((
                                            TownLoadChoice {
                                                name: save.name.clone(),
                                                path: save.path.clone(),
                                                protected: save.protected,
                                            },
                                            Button,
                                            TabIndex(i32::try_from(index).unwrap_or(i32::MAX)),
                                            authored_ui_image(
                                                render,
                                                MAIN_MENU_TEXTURE_PATHS[0],
                                                main_menu_texture(render, MAIN_MENU_TEXTURE_PATHS[0]),
                                            ),
                                            Node {
                                                width: percent(100.0),
                                                height: px(45),
                                                flex_shrink: 0.0,
                                                justify_content: JustifyContent::Center,
                                                align_items: AlignItems::Center,
                                                ..default()
                                            },
                                        ))
                                        .with_children(|button| {
                                            button.spawn((
                                                Text::new(save.name.clone()),
                                                TextFont {
                                                    font_size: FontSize::Px(18.0),
                                                    ..default()
                                                },
                                                TextColor(Color::srgb(0.827, 0.745, 0.498)),
                                                Pickable::IGNORE,
                                            ));
                                        });
                                    }
                                });
                            panel
                                .spawn(Node {
                                    width: percent(100.0),
                                    justify_content: JustifyContent::Center,
                                    ..default()
                                })
                                .with_children(|buttons| {
                                    spawn_town_dialog_button(
                                        buttons,
                                        TownDialogAction::Back,
                                        "Back",
                                        render,
                                        i32::try_from(saves.len()).unwrap_or(i32::MAX),
                                    );
                                });
                        }
                        panel.spawn((
                            TownDialogFeedback,
                            Text::new(""),
                            TextFont {
                                font_size: FontSize::Px(15.0),
                                ..default()
                            },
                            TextLayout::justify(Justify::Center),
                            TextColor(Color::srgb(1.0, 0.70, 0.38)),
                            Pickable::IGNORE,
                            Node {
                                width: percent(100.0),
                                min_height: px(20),
                                ..default()
                            },
                        ));
                    });
            });
    }
}

