    fn gate_trigger_matches_the_authored_four_unit_box() {
        let gate = Vec3::new(10.0, 5.0, -4.0);
        assert!(gate_trigger_contains(
            gate,
            Vec3::new(12.0, 100.0, -6.0),
            2.0
        ));
        assert!(!gate_trigger_contains(
            gate,
            Vec3::new(12.001, 5.0, -4.0),
            2.0
        ));
        assert!(!gate_trigger_contains(
            gate,
            Vec3::new(10.0, 5.0, -6.001),
            2.0
        ));
    }

    #[test]
